parameters.jsCode:
// El analisis se hace AQUI y el modelo solo redacta: recibe la operacion, el tipo
// de inmueble, el angulo ya elegido y las cifras ya calculadas. No puede inventarse
// un dato ni hablar de 'su piso' cuando lo que se vende es una nave.
const body = $('Webhook Lead Gen').first().json.body || {};
const agente = body.agent || 'Josep';

const filas = $('Consultar Propiedad').all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && r.id != null; });
const cap = filas[0];

function texto(n) { return String(n == null ? '' : n).trim(); }

// Idealista devuelve el barrio como "Subdistrict Els Orriols" / "District Camins".
// Ese prefijo en ingles se colaba literal en el mensaje y delataba que era automatico.
// Espacio literal en vez de \s: este workflow se genera desde cadenas JS y el escape
// se perdia por el camino, dejando la expresion sin efecto.
function zona(b) {
  // Solo se quita el prefijo en ingles de Idealista. El 'Zona '/'Barrio ' del
  // propio toponimo se respeta: recortarlo daba 'la zona de de Favara' a partir
  // de 'Zona de Favara'. Quien pone la preposicion es la frase, no el nombre.
  return texto(b).replace(/^(sub)?district +/i, '').trim();
}

// El scraper antiguo guardaba literales como "No especificada" en vez de dejar el
// campo vacio. Colarselos al modelo solo sirve para que escriba "su piso, planta no
// especificada": si no hay dato, mejor no mencionarlo.
const VACIOS = ['no especificada', 'no especificado', 'sin especificar', 'sin identificar', 'desconocido', 'n/a', '-'];

// Cuando el anuncio no trae nombre, el scraper guarda el literal 'Propietario'.
// Tratarlo como un nombre de verdad daba 'Hola Propietario, soy Josep' y una
// ficha con 'Propietario: Propietario'. Mejor no saludar por el nombre.
function nombrePila(v) {
  const t = texto(v);
  if (!t) return '';
  const b = t.toLowerCase();
  if (b === 'propietario' || b === 'propietaria' || b === 'particular') return '';
  return t.split(/[ ,]/)[0];
}
function dato(v) {
  const t = texto(v);
  return t && VACIOS.indexOf(t.toLowerCase()) === -1 ? t : null;
}

if (!cap) {
  return [{ json: { ok: false, fallback: 'Hola, he visto su anuncio en Idealista y me gustaria comentarle una cosa. Un saludo, ' + agente } }];
}

const rd = cap.raw_data || {};
const mc = rd.moreCharacteristics || {};

// ---- VENTA o ALQUILER ----
// La tabla mezcla las dos cosas: el mismo mensaje para ambas es el error mas caro
// posible, porque a quien alquila se le estaria hablando de vender.
let operacion = rd.operation;
if (operacion !== 'sale' && operacion !== 'rent') {
  // Red de seguridad si falta el dato: un precio de tres o cuatro cifras solo puede
  // ser una renta mensual, nunca el precio de venta de un inmueble.
  const p = Number(cap.precio);
  operacion = (p > 0 && p < 10000) ? 'rent' : 'sale';
}
const esAlquiler = operacion === 'rent';

// ---- QUE TIPO DE INMUEBLE ES ----
// Sin esto, a quien vende un local se le escribe 'su piso' y se le habla de plantas
// sin ascensor. Los valores salen del propio actor (homes/premises/garages/...).
// compra/alquila son sujetos SIN verbo ('inversores y negocios'), nunca
// 'inversores buscando local': el verbo lo pone cada frase. Al llevarlo dentro
// salian cosas como 'tienes negocios buscando local buscando por ahi'.
const TIPOS = {
  homes:        { que: 'la vivienda',        suyo: 'su vivienda',        busca: 'vivienda',        compra: 'compradores',             alquila: 'inquilinos' },
  rooms:        { que: 'la habitacion',      suyo: 'su habitacion',      busca: 'habitacion',      compra: 'compradores',             alquila: 'inquilinos' },
  premises:     { que: 'el local',           suyo: 'su local',           busca: 'local',           compra: 'inversores y negocios',   alquila: 'negocios' },
  offices:      { que: 'la oficina',         suyo: 'su oficina',         busca: 'oficina',         compra: 'empresas e inversores',   alquila: 'empresas' },
  garages:      { que: 'la plaza de garaje', suyo: 'su plaza de garaje', busca: 'plaza de garaje', compra: 'compradores de la zona',  alquila: 'vecinos de la zona' },
  lands:        { que: 'el terreno',         suyo: 'su terreno',         busca: 'suelo',           compra: 'promotores e inversores', alquila: 'interesados' },
  storageRooms: { que: 'el trastero',        suyo: 'su trastero',        busca: 'trastero',        compra: 'compradores de la zona',  alquila: 'vecinos de la zona' },
};
const tipoBruto = rd.propertyType || 'homes';
const T = TIPOS[tipoBruto] || { que: 'el inmueble', suyo: 'su inmueble', busca: 'inmuebles asi', compra: 'compradores', alquila: 'inquilinos' };
const esVivienda = tipoBruto === 'homes' || tipoBruto === 'rooms';
const esComercial = tipoBruto === 'premises' || tipoBruto === 'offices';
const CLIENTES = esAlquiler ? T.alquila : T.compra;

function eur(n) { return n == null ? null : Number(n).toLocaleString('es-ES') + ' EUR' + (esAlquiler ? '/mes' : ''); }

// 1 de cada 4 captaciones no trae barrio, pero todas llevan alguna referencia
// geografica en raw_data.ubication. Sin este rescate el modelo se inventaba la zona
// a partir del nombre de la calle.
const ub = rd.ubication || {};
const BARRIO = zona(cap.barrio)
  || zona(ub.administrativeAreaLevel4)
  || zona(ub.administrativeAreaLevel3)
  || zona(String(ub.locationName || '').split(',')[0])
  || zona(ub.administrativeAreaLevel2)
  || '';
// 'la zona de ' + barrio se rompe con nombres que ya traen articulo o
// preposicion: 'Zona de Favara' daba 'la zona de Zona de Favara', y 'de Favara'
// daba 'la zona de de Favara'.
// Espacios literales en vez de \b y \s: este codigo se genera desde cadenas JS y
// las barras invertidas se pierden por el camino. Ya ha pasado tres veces.
let LUGAR;
if (!BARRIO) LUGAR = 'su zona de Valencia';
else if (/^(zona|barrio|poligono|urbanizacion) /i.test(BARRIO)) LUGAR = 'la ' + BARRIO.charAt(0).toLowerCase() + BARRIO.slice(1);
else if (/^(de|del|dels|d.) /i.test(BARRIO)) LUGAR = 'la zona ' + BARRIO;
else LUGAR = 'la zona de ' + BARRIO;

// ---- antiguedad del anuncio ----
const ts = rd.modificationDate && rd.modificationDate.value;
const dias = ts ? Math.floor((Date.now() - Number(ts)) / 86400000) : null;

// ---- hora local en Espana ----
// El modelo saludaba a ojo y solto un 'Buenas tardes' a las 11:12 de la manana.
// El servidor de n8n va en UTC, asi que la hora hay que calcularla con la zona
// horaria puesta a mano. Se le pasa la hora y que elija el saludo el, en vez de
// darle el texto ya escrito: asi no viajan acentos por el generador de codigo.
let HORA_ES = '';
try {
  HORA_ES = new Intl.DateTimeFormat('es-ES', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());
} catch (e) { HORA_ES = ''; }

// ---- detalles del INMUEBLE que se le pueden mencionar ----
// Solo rasgos del inmueble, nunca de como esta hecho el anuncio. Aqui hubo
// 'el anuncio tiene solo 2 fotos' y 'la descripcion es muy escueta', y en la
// prueba en vivo el modelo escribio 'Observo que su anuncio tiene solo dos
// fotografias': es criticarle el trabajo al propietario en el primer mensaje,
// lo contrario de lo que se busca. Lo mismo con '3o sin ascensor', que es
// senalarle un defecto. Todo eso fuera.
// Ademas van filtrados por tipo: a quien vende una nave no se le habla de
// plantas ni de ascensores.
const bajada = cap.precio_anterior != null && Number(cap.precio) < Number(cap.precio_anterior);
const señales = [];
if (cap.estado === 'A reformar') señales.push('esta a reformar, y hay quien busca justo eso para dejarlo a su gusto');
// Salida de humos: es lo primero que pregunta cualquiera que quiera montar
// hosteleria, y solo lo trae el anuncio de un local.
if (esComercial && mc.smokeExtractor === true) señales.push('tiene salida de humos, que es lo primero que preguntan los negocios de hosteleria');
if (cap.metros) señales.push('son ' + cap.metros + ' m2');
if (esVivienda && Number(cap.habitaciones) >= 3) señales.push('tiene ' + cap.habitaciones + ' habitaciones');

// ---- eleccion del angulo (determinista, por prioridad) ----
// Todos apuntan a lo mismo: que YA hay clientes buscando en su zona. Es lo unico
// que le da al propietario una razon concreta para fiarse y contestar. Nada de
// meterle prisa ni de decirle que su anuncio esta mal: eso genera rechazo.
// Los mercados finos (locales, garajes) se mueven mas despacio que la vivienda.
const UMBRAL_ESTANCADO = esComercial ? 60 : (esAlquiler ? 30 : 45);
let angulo, gancho;

if (bajada) {
  angulo = 'bajada_de_precio';
  gancho = 'Ha ajustado el precio de ' + eur(cap.precio_anterior) + ' a ' + eur(cap.precio) +
    '. Menciona el ajuste con naturalidad, SIN dar a entender que estaba caro, y ofrecele que antes de volver a bajarlo vea los ' + CLIENTES + ' que ya estas moviendo en ' + LUGAR + '.';
} else if (dias != null && dias >= UMBRAL_ESTANCADO) {
  angulo = 'anuncio_estancado';
  gancho = 'Llevas unas ' + Math.floor(dias / 7) + ' semanas viendo el anuncio publicado. Dilo como que le sigues la pista porque trabajas ' + LUGAR +
    ', y que en ese tiempo te han pasado por delante ' + CLIENTES + ' que encajaban con ' + T.suyo + '. NO insinues que el anuncio o el precio esten mal.';
} else if (dias != null && dias <= 3) {
  angulo = 'recien_publicado';
  gancho = 'Acabas de ver el anuncio. Di que trabajas ' + LUGAR + ' y que justo ahora tienes ' + CLIENTES +
    ' buscando por ahi. NO le avises de que va a recibir muchas llamadas: eso es meterle presion, no ayudarle.';
} else {
  angulo = 'generico';
  gancho = 'Sin gancho de datos: ve directo. Trabajas ' + LUGAR + ' y tienes ' + CLIENTES +
    ' ahi ahora mismo; ofrecele conocer esos perfiles.';
}

if (señales.length && angulo !== 'generico') {
  gancho += ' Puedes mencionar ademas un detalle real del inmueble, como algo que has visto tu del anuncio y no como un requisito de tus clientes: ' + señales[0] + '.';
}

// ---- ficha, con los campos que tienen sentido para este tipo ----
const ETIQUETA = { homes: 'VIVIENDA', rooms: 'HABITACION', premises: 'LOCAL O NAVE', offices: 'OFICINA', garages: 'GARAJE', lands: 'TERRENO', storageRooms: 'TRASTERO' };
const ficha = [
  'Tipo de inmueble: ' + (ETIQUETA[tipoBruto] || 'INMUEBLE') + '   Operacion: ' + (esAlquiler ? 'ALQUILER' : 'VENTA'),
  'Propietario: ' + (nombrePila(cap.nombre) || 'no publica su nombre. Saluda sin nombre y NUNCA le llames Propietario.'),
  'Direccion: ' + (texto(cap.calle) || 'no publicada en el anuncio'),
  'Zona: ' + (BARRIO || 'no especificada'),
  (esAlquiler ? 'Renta: ' : 'Precio: ') + (eur(cap.precio) || 'no especificado'),
  cap.metros ? 'Superficie: ' + cap.metros + ' m2' : null,
  esVivienda && cap.habitaciones ? 'Habitaciones: ' + cap.habitaciones : null,
  esVivienda && cap.banos ? 'Banos: ' + cap.banos : null,
  esComercial && mc.bathNumber ? 'Aseos: ' + mc.bathNumber : null,
  esComercial && mc.roomDistributionNumber ? 'Estancias: ' + mc.roomDistributionNumber : null,
  esComercial && mc.smokeExtractor === true ? 'Tiene salida de humos' : null,
  esVivienda && dato(cap.planta) ? 'Planta: ' + dato(cap.planta) : null,
  dato(cap.estado) ? 'Estado: ' + dato(cap.estado) : null,
  dias != null ? 'Anuncio actualizado hace ' + dias + ' dias' : null,
  señales.length ? 'Detalles que puedes mencionar: ' + señales.join('; ') : null,
].filter(Boolean).join('\n');

// ---- plantillas de estilo ----
// Venta de vivienda: del Google Doc que ya usaba el generador antiguo.
// Alquiler de vivienda: el generador de alquiler antiguo no usaba Google Docs,
// llevaba su plantilla en el prompt. Se conserva literal porque es el discurso
// que funciona: perfiles solventes y seguro de impago aprobado.
// El nodo de Google Docs de n8n NO devuelve la estructura cruda de la API de
// Google: devuelve { documentId, content } con el texto ya plano. Esta funcion
// leia d.body.content, que no existe, asi que devolvia siempre cadena vacia y
// el prompt salia SIN plantilla. Es decir: los 20.000 caracteres de plantillas
// escritas a mano no se han usado NUNCA. Se admiten las dos formas.
function docToTexto(d) {
  if (!d) return '';
  if (typeof d.content === 'string') return d.content.trim();
  if (typeof d === 'string') return d.trim();
  const bloques = (d.body && d.body.content) || [];
  let out = '';
  for (const b of bloques) {
    for (const el of ((b.paragraph && b.paragraph.elements) || [])) {
      if (el.textRun && el.textRun.content) out += el.textRun.content;
    }
    for (const fila of ((b.table && b.table.tableRows) || [])) {
      for (const celda of (fila.tableCells || [])) {
        for (const c of (celda.content || [])) {
          for (const el of ((c.paragraph && c.paragraph.elements) || [])) {
            if (el.textRun && el.textRun.content) out += el.textRun.content;
          }
        }
      }
    }
  }
  return out.trim();
}

// El documento esta organizado por situacion, con titulos que coinciden casi uno
// a uno con los angulos que calcula este codigo. Meter los 20.000 caracteres
// enteros en el prompt seria caro y ademas confundiria al modelo con ejemplos de
// situaciones que no son la de este propietario: se le pasa SOLO su seccion, y
// unas pocas frases, que es lo que hace falta para copiar el tono.
const SECCION_POR_ANGULO = {
  bajada_de_precio: 'Bajada de Precio',
  anuncio_estancado: 'Antiguedad Del Anuncio',
  recien_publicado: 'Actualizacion',
  generico: 'Valor de Mercado',
};
function sinTildes(s) { return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim(); }
function seccionDelDoc(texto, titulo, maxEjemplos) {
  const lineas = String(texto).split('\n');
  const buscado = sinTildes(titulo).replace(/:$/, '');
  // Un titulo es una linea corta que no es un mensaje (los mensajes empiezan por Hola)
  const esTitulo = function (l) {
    const t = l.trim();
    return t.length > 0 && t.length < 60 && !/^(hola|\u{1F4E9})/iu.test(t);
  };
  let i = lineas.findIndex(function (l) { return esTitulo(l) && sinTildes(l).replace(/:$/, '') === buscado; });
  if (i === -1) return '';
  const out = [];
  for (let k = i + 1; k < lineas.length && out.length < maxEjemplos; k++) {
    const t = lineas[k].trim();
    if (!t) continue;
    if (esTitulo(lineas[k])) break;
    out.push(t);
  }
  return out.join('\n');
}

const PLANTILLA_ALQUILER_VIVIENDA = [
  'Hola, le escribo por la vivienda situada en *[DIRECCION]*.',
  '',
  'Queria comentarle que actualmente dispongo de *inquilinos solventes*, que ademas cuentan con el *Seguro de Impago Caser aprobado*, lo que aporta mayor seguridad y tranquilidad al propietario.',
  '',
  'Si la vivienda continua disponible para alquiler, puedo presentarle estos perfiles de forma *totalmente gratuita y sin ningun compromiso*.',
  '',
  'Le interesaria conocer estos perfiles?',
].join('\n');

const usaPlantillaAlquiler = esAlquiler && esVivienda;
let plantillas = '';
if (usaPlantillaAlquiler) plantillas = PLANTILLA_ALQUILER_VIVIENDA;
else if (!esAlquiler && esVivienda) {
  try {
    const doc = docToTexto($input.first().json);
    plantillas = seccionDelDoc(doc, SECCION_POR_ANGULO[angulo] || 'Valor de Mercado', 6);
    // Si el titulo cambia en el documento, mejor las primeras frases que nada
    if (!plantillas) plantillas = doc.split('\n').filter(function (l) { return /^\s*(hola|\u{1F4E9})/iu.test(l); }).slice(0, 5).join('\n');
  } catch (e) { plantillas = ''; }
}

// ---- que le ofreces, segun tipo y operacion ----
// El seguro de impago Caser se menciona SOLO en alquiler de vivienda, que es de
// donde salio ese discurso. Extenderlo a un local seria afirmar algo que no consta.
let oferta;
if (esAlquiler && esVivienda) {
  oferta = 'Tienes inquilinos solventes ya buscando, con Seguro de Impago Caser aprobado, y puedes presentarle esos perfiles gratis y sin compromiso.';
} else if (esAlquiler && esComercial) {
  oferta = 'Tienes ' + CLIENTES + ' buscando ' + T.busca + ' en la zona, con solvencia ya comprobada, y puedes presentarle esos perfiles gratis y sin compromiso. Tambien te encargas del contrato y de la seleccion.';
} else if (esAlquiler) {
  oferta = 'Tienes ' + CLIENTES + ' buscando ' + T.busca + ' y puedes presentarle esos perfiles gratis y sin compromiso.';
} else if (esComercial) {
  oferta = 'Trabajas ' + LUGAR + ' y tienes ' + CLIENTES + ' buscando ' + T.busca + '. Puedes encargarte de la operacion: ensenarle los perfiles, filtrar las visitas de curiosos, negociar y llevar el papeleo.';
} else if (esVivienda) {
  oferta = 'Trabajas ' + LUGAR + ' y tienes ' + CLIENTES + ' buscando ' + T.busca + '. Puedes encargarte tu de la venta: ensenarle los perfiles que ya tienes, filtrar las visitas para que no le pasee gente por casa sin motivo, negociar y llevar el papeleo.';
} else {
  // Garajes, terrenos y trasteros: aqui no hay visitas que filtrar ni gente
  // paseandose por casa. Con la rama de vivienda salia 'que no le pasee gente
  // por casa' para una plaza de garaje.
  oferta = 'Trabajas ' + LUGAR + ' y tienes ' + CLIENTES + ' buscando ' + T.busca + '. Puedes encargarte tu de la venta: ensenarle los perfiles que ya tienes, cerrar la operacion y llevar el papeleo.';
}

// El objetivo del primer mensaje no es cerrar nada: es que el propietario se fie lo
// suficiente como para contestar. Por eso las reglas van casi todas sobre el tono.
const comun = [
  'REGLAS INNEGOCIABLES:',
  '1. Usa UNICAMENTE los datos de la ficha y el angulo indicado. Puedes decir que tienes clientes buscando en su zona, pero NUNCA te inventes cuantos son, ni sus nombres, ni presupuestos, ni plazos, ni datos de mercado.',
  '1b. Tampoco les atribuyas requisitos: nada de "busco compradores de unos 80 m2" ni "quieren tres habitaciones". Los detalles de la ficha son del inmueble, no criterios de tus clientes.',
  '2. Desarrolla el angulo indicado: es lo que hace que el mensaje no parezca una plantilla masiva.',
  '3. GENERAR CONFIANZA ES EL OBJETIVO. Prohibido: meter prisa o urgencia, avisar de que le van a llover llamadas, insinuar que su precio esta mal, que su anuncio esta mal hecho o que no va a vender solo. Nada de "no deje pasar esta oportunidad", "somos lideres del sector" ni "tengo el comprador perfecto".',
  '4. Habla como una persona que conoce esa zona, no como una agencia mandando circulares. Nombra la zona.',
  '5. Referirte al inmueble SIEMPRE como "' + T.suyo + '". Nunca lo llames de otra forma: es ' + (ETIQUETA[tipoBruto] || 'un inmueble') + ', no otra cosa.',
  '6. En el primer mensaje ofreces algo sin pedirle nada. No pidas cita, ni exclusividad, ni datos.',
  '7. Maximo 90 palabras.',
  '8. Termina con UNA pregunta corta y facil de responder.',
  (HORA_ES ? '8b. En Espana son las ' + HORA_ES + ' ahora mismo. Si empiezas saludando por el momento del dia, que corresponda a esa hora. Ante la duda, saluda sin mencionar la hora.' : '8b. No saludes mencionando el momento del dia: no sabes a que hora se enviara.'),
  '9. Firma como ' + agente + '. Nunca digas que eres una IA ni que el mensaje es automatico.',
  '9b. NUNCA digas de que agencia o inmobiliaria eres, ni su nombre, ni "le escribo desde...". Presentate solo con tu nombre. Esto manda por encima de la plantilla de referencia: si la plantilla nombra una agencia, quitalo. Si el propietario pregunta, ya se lo dira ' + agente + ' en persona.',
  '10. Devuelve SOLO el texto del mensaje: sin comillas, sin encabezados, sin explicaciones.',
];

const cabecera = 'Eres ' + agente + ', agente inmobiliario en Valencia que trabaja esa zona. Escribes el PRIMER mensaje de WhatsApp a un particular que ' +
  (esAlquiler ? 'ALQUILA ' : 'VENDE ') + T.que + ' por su cuenta en Idealista.';

const bloques = [cabecera, '', 'LO QUE LE OFRECES (es tu propuesta de valor, no la cambies):', oferta, ''];

if (plantillas) {
  bloques.push('PLANTILLA DE REFERENCIA (respeta su tono, su estructura y su longitud):', plantillas, '');
}

if (usaPlantillaAlquiler) {
  bloques.push('ESPECIFICO:', 'a. Trato de USTED, como la plantilla.', 'b. Resalta con *asteriscos* los dos o tres conceptos clave, formato de WhatsApp.', 'c. Nada de emojis.', '');
} else if (esComercial) {
  bloques.push('ESPECIFICO:', 'a. Trato de usted: en comercial se espera mas formalidad que en vivienda.', 'b. Nada de emojis.', 'c. Habla de metros, ubicacion y rentabilidad, no de habitaciones ni de comodidad para vivir.', '');
} else if (plantillas) {
  bloques.push('ESPECIFICO:', 'a. Usa el MISMO trato (tu o usted) que la plantilla: no lo cambies por tu cuenta.', 'b. Como mucho un emoji, y solo si la plantilla los usa.', '');
} else {
  bloques.push('ESPECIFICO:', 'a. Trato de usted.', 'b. Nada de emojis.', '');
}

const sistema = bloques.concat(comun).join('\n');

const prompt = [
  'FICHA DEL INMUEBLE',
  ficha,
  '',
  'ANGULO A USAR: ' + angulo,
  gancho,
  '',
  'Redacta el mensaje.',
].join('\n');

// ---- fallback si el modelo falla ----
const donde = (cap.calle ? ' de ' + texto(cap.calle) : '') + (BARRIO ? ' en ' + BARRIO : '');
const saludo = nombrePila(cap.nombre) ? 'Hola ' + nombrePila(cap.nombre) + ', ' : 'Hola, ';
const fallback = (saludo + 'soy ' + agente + '. He visto su anuncio' + donde +
  ' en Idealista. Trabajo esa zona y ahora mismo tengo ' + CLIENTES + ' buscando ' + T.busca + '. Si le interesa, le puedo ensenar esos perfiles sin ningun compromiso. Le va bien?').replace(/  +/g, ' ').trim();

return [{
  json: {
    ok: true,
    operacion: operacion,
    tipo: tipoBruto,
    angulo: angulo,
    dias_publicado: dias,
    sistema: sistema,
    prompt: prompt,
    fallback: fallback,
  },
}];
